<?php
namespace App\Services;
use App\Models\Customer;use App\Models\InventoryStock;use App\Models\Notification;
class AlertService{
 public function generateForBusiness(int $businessId):void{$keys=[];$stocks=InventoryStock::with(['product:id,business_id,name','branch:id,name'])->whereHas('product',fn($q)=>$q->where('business_id',$businessId))->whereColumn('quantity','<=','reorder_level')->get();foreach($stocks as $stock){$key='low-stock-'.$stock->id;$keys[]=$key;Notification::updateOrCreate(['business_id'=>$businessId,'dedupe_key'=>$key],['type'=>'low_stock','title'=>'Low stock: '.$stock->product->name,'body'=>$stock->branch->name.' has '.$stock->quantity.' remaining (reorder at '.$stock->reorder_level.').','severity'=>'warning']);}$customers=Customer::where('business_id',$businessId)->where('current_due','>',0)->whereDate('due_since','<',now()->subDays(30))->get();foreach($customers as $customer){$key='overdue-customer-'.$customer->id;$keys[]=$key;Notification::updateOrCreate(['business_id'=>$businessId,'dedupe_key'=>$key],['type'=>'overdue','title'=>'Overdue balance: '.$customer->name,'body'=>'Outstanding balance is '.$customer->current_due.' since '.$customer->due_since?->format('Y-m-d').'.','severity'=>'danger']);}$stale=Notification::where('business_id',$businessId)->whereIn('type',['low_stock','overdue']);if($keys)$stale->whereNotIn('dedupe_key',$keys);$stale->delete();}
}
